mf.group('base',()=>{
  // 简洁圆形底座
  mf.box([-15,0,-15],[30,2,30],{style:S.stone});
  mf.box([-13,2,-13],[26,1,26],{style:S.steel});
});
mf.group('skirt',()=>{
  // 裙身: A字, 逐层外扩
  const layers=[[3,13,7],[6,12,7],[10,11,7],[13,10,8],[16,9,8]];
  // y, halfW, depth...
  let rows=[[3,13,7],[6,12,7],[10,11,7],[13,10,8],[16,9,8]];
  rows.forEach(([h,hw,hd])=>{
    // skirt flares downward: build from y=3 up
  });
  // 下摆最宽
  const bands=[[3,2,15,11],[5,5,13,10],[10,4,11,9],[14,3,9,8]];
  bands.forEach(([y,hh,hw,hd])=>{
    mf.box([-hw,y,-hd],[hw*2,hh,hd*2],{style:S.blue});
  });
  // 白色荷叶边内衬（裙底边缘）
  mf.box([-16,3,-12],[32,2,24],{style:S.snow});
  mf.box([-14,5,-10],[28,1,20],{style:S.snow});
});
mf.group('torso',()=>{
  mf.box([-5,17,-4],[10,3,8],{style:S.blue});
  mf.box([-4,20,-4],[8,5,8],{style:S.blue});
  mf.box([-4,20,4],[8,5,1],{style:S.snow}); // 白色胸襟
});
"}

