{"baseRevision": 1, "code": "const S={blue:3,cloud:19,snow:7,stone:1,storm:20,steel:10,ice:18,gold:11,rubber:24};
const hair=S.blue, skin=S.cloud, white=S.snow;
mf.group('head',()=>{
  // 大头小身: 头 14 宽
  mf.box([-7,26,-6],[14,12,12],{style:skin});
  // 脸颊下收
  mf.box([-6,25,-5],[12,1,10],{style:skin});
  // 脸(前+Z)
  mf.box([-5,27,6],[10,8,1],{style:skin});
  // 眼
  mf.box([-4,30,7],[3,3,1],{style:S.storm});
  mf.box([1,30,7],[3,3,1],{style:S.storm});
  mf.box([-3,31,8],[1,1,1],{style:white});
  mf.box([2,31,8],[1,1,1],{style:white});
  // 嘴
  mf.box([-1,28,7],[2,1,1],{style:S.rubber});
  // 腮红
});
mf.group('hair',()=>{
  // 头顶盖
  mf.box([-8,36,-7],[16,4,14],{style:hair});
  mf.box([-7,40,-6],[14,2,12],{style:hair});
  // 刘海
  mf.box([-7,32,7],[14,4,1],{style:hair});
  mf.box([-2,29,7],[4,3,1],{style:hair});
  // 侧发（贴脸两侧，向下成束）
  [-1,1].forEach(s=>{
    const x0=s<0?-9:6;
    mf.box([x0,26,-7],[3,12,15],{style:hair});
    mf.box([s<0?-9:5,18,-6],[4,9,12],{style:hair});
    mf.box([s<0?-8:4,10,-5],[4,9,9],{style:hair});
    mf.box([s<0?-7:3,7,-4],[4,4,6],{style:S.ice}); // 发梢亮色
  });
  // 后发
  mf.box([-7,20,-10],[14,18,4],{style:hair});
  mf.box([-6,12,-10],[12,9,3],{style:hair});
  mf.box([-5,8,-9],[10,5,2],{style:S.ice});
  // 呆毛
  mf.box([-1,42,-1],[3,1,3],{style:hair});
  mf.box([2,43,-1],[1,3,2],{style:hair});
  // 女仆发箍（白色褶皱）
  mf.box([-8,38,-6],[16,2,2],{style:white});
  mf.box([-7,37,6],[14,2,2],{style:white});
  mf.box([-9,37,-5],[2,2,11],{style:white});
  mf.box([7,37,-5],[2,2,11],{style:white});
  // 头发上的蓝缎带
  mf.box([-9,34,-2],[2,3,5],{style:S.ice});
  mf.box([7,34,-2],[2,3,5],{style:S.ice});
});
mf.group('fins',()=>{
  // 头侧鲸鳍耳
  [-1,1].forEach(s=>{
    for(let i=0;i<5;i++){
      const x=s<0? -8-i : 7+i;
      mf.box([x,31-i,-1],[1,3-i>0?3-i:1,4],{style:S.storm});
    }
  });
});
mf.group('tail',()=>{
  // 身后大鲸尾, 从右后(-Z,+X)伸出并翘起
  const pts=[[6,6,-11],[9,7,-14],[12,9,-17],[14,12,-19]];
  mf.box([6,5,-13],[3,4,4],{style:S.storm});
  mf.box([9,6,-16],[3,4,4],{style:S.storm});
  mf.box([12,8,-19],[3,5,4],{style:S.storm});
  mf.box([14,11,-21],[3,4,3],{style:S.storm});
  // 尾鳍左右张开
  mf.box([13,14,-22],[3,3,7],{style:S.storm});
  mf.box([17,16,-20],[3,6,3],{style:S.storm});
  mf.box([11,16,-24],[3,5,3],{style:S.storm});
});
", "mode": "apply", "seed": 7}

