{"baseRevision": 2, "code": "const S={blue:3,cloud:19,snow:7,stone:1,storm:20,steel:10,ice:18,gold:11,rubber:24,wood:2};
const white=S.snow, blue=S.blue, navy=S.blue;
mf.group('apron',()=>{
  // 围裙主体：白色，覆盖胸前到裙面
  mf.box([-5,13,7],[10,9,1],{style:white});
  mf.box([-6,11,8],[12,3,1],{style:white});
  mf.box([-4,22,4],[8,3,1],{style:white}); // 胸襟
  // 荷叶边外框
  mf.box([-7,12,8],[1,8,1],{style:white});
  mf.box([6,12,8],[1,8,1],{style:white});
  mf.box([-7,12,8],[14,1,1],{style:white});
  mf.box([-7,11,8],[14,1,1],{style:white});
  // 荷叶边锯齿
  for(let i=0;i<7;i++){
    mf.box([-7+i*2,10,8],[1,1,1],{style:white});
  }
  // 围裙上的小鲸鱼图案(深蓝)
  mf.box([-2,16,9],[4,2,1],{style:S.storm});
  mf.box([2,17,9],[2,2,1],{style:S.storm});
  mf.box([-1,18,9],[1,2,1],{style:S.storm});
});
mf.group('detail',()=>{
  // 领口蝴蝶结
  mf.box([-1,24,6],[3,2,1],{style:S.rubber});
  mf.box([-3,24,5],[2,2,1],{style:white});
  mf.box([2,24,5],[2,2,1],{style:white});
  // 腰封与金扣
  mf.box([-5,18,-4],[10,2,10],{style:S.rubber});
  mf.box([-4,18,5],[3,1,1],{style:S.gold});
  mf.box([1,18,5],[3,1,1],{style:S.gold});
  // 袖子
  [-1,1].forEach(s=>{
    const x=s<0?-8:6;
    mf.box([x,15,-2],[2,6,5],{style:blue});
    mf.box([x,21,-2],[3,2,5],{style:blue});
    mf.box([s<0?-9:6,13,-2],[2,2,4],{style:white}); // 袖口荷叶边
    mf.box([s<0?-7:5,8,-1],[2,5,3],{style:S.cloud}); // 手
  });
  // 裙面金色纹样与蝴蝶结
  mf.box([-13,6,-2],[4,1,4],{style:S.gold});
  mf.box([9,6,-2],[4,1,4],{style:S.gold});
  mf.box([-12,7,-2],[2,1,2],{style:S.gold});
  mf.box([10,7,-2],[2,1,2],{style:S.gold});
});
mf.group('legs',()=>{
  [-1,1].forEach(s=>{
    const x=s<0?-4:1;
    mf.box([x,1,6],[3,4,3],{style:white});  // 白袜
    mf.box([x,0,5],[3,2,5],{style:S.blue});  // 蓝鞋
  });
});
", "mode": "apply", "seed": 7}

